import subprocess
# Use nm to find the nearest symbol below each address
addrs = [0x2f4b20, 0x2f4c84]
result = subprocess.run(['nm', '-C', '--defined-only', 'mono.debug'], capture_output=True, text=True)
symbols = []
for line in result.stdout.splitlines():
    parts = line.split()
    if len(parts) >= 3:
        try:
            addr = int(parts[0], 16)
            symbols.append((addr, parts[1], ' '.join(parts[2:])))
        except ValueError:
            pass
symbols.sort()
for target in addrs:
    # find nearest symbol <= target
    best = None
    for addr, typ, name in symbols:
        if addr <= target:
            best = (addr, name)
        else:
            break
    if best:
        print(f'0x{target:x} -> {best[1]} + 0x{target - best[0]:x}')
    else:
        print(f'0x{target:x} -> ???')
"

