import subprocess
# $d symbols are data markers in ARM - use FUNC symbols instead
result = subprocess.run(['readelf', '-sW', 'mono.debug'], capture_output=True, text=True)
symbols = []
for line in result.stdout.splitlines():
    parts = line.split()
    if len(parts) >= 8 and 'FUNC' in parts:
        try:
            addr = int(parts[1], 16)
            size = int(parts[2])
            name = parts[7] if len(parts) > 7 else parts[-1]
            symbols.append((addr, size, name))
        except (ValueError, IndexError):
            pass
symbols.sort()
targets = [0x222098, 0x2241ac, 0x1abc80, 0x16de04, 0x2f4b20, 0x2f4c84, 0x2c1a40]
for target in targets:
    best = None
    for addr, size, name in symbols:
        if addr <= target < addr + size:
            best = (addr, size, name)
            break
        elif addr <= target:
            best = (addr, size, name)
        elif addr > target:
            break
    if best:
        print(f'0x{target:x} -> {best[2]} + 0x{target - best[0]:x}')
    else:
        print(f'0x{target:x} -> ???')
"

